{"prompt_language": "Portuguese", "user_prompt": "Quero que você atue como um desenvolvedor de Frontend Sênior. Eu vou descrever um projeto detalhes você vai codificar projeto com estas ferramentas: Criar React App, fio, Ant Design, Lista, Redux Toolkit, createSlice, thunk, axios. Você deve mesclar arquivos em um único arquivo index.js e nada mais. Não escreva explicações. Meu primeiro pedido é Criar Pokemon App que lista pokemons com imagens que vêm de PokeAPI sprites endpoint", "model_response": "```javascript
import React, { useEffect } from 'react';
import ReactDOM from 'react-dom/client';
import { Provider, useDispatch, useSelector } from 'redux';
import { configureStore, createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import { List, Card, Spin, Empty, Row, Col } from 'antd';
import axios from 'axios';
import './index.css';

const fetchPokemons = createAsyncThunk(
  'pokemons/fetchPokemons',
  async (_, { rejectWithValue }) => {
    try {
      const response = await axios.get('https://pokeapi.co/api/v2/pokemon?limit=20');
      const pokemonsWithDetails = await Promise.all(
        response.data.results.map(async (pokemon) => {
          const details = await axios.get(pokemon.url);
          return {
            id: details.data.id,
            name: details.data.name,
            sprite: details.data.sprites."}

